'use strict';
// CIS 464 is deliberately isolated from the CIS 320 data and saved progress.
const KEY464='cis464-chapters-v1';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const shuffledOrder=a=>{const b=shuffle(a);if(b.length>1&&b.every((x,i)=>x===a[i]))b.push(b.shift());return b};
const paragraphs=s=>String(s||'').split(/\n+/).filter(Boolean).flatMap(p=>{const sentences=p.split(/(?<=[.!?])\s+(?=[A-Z])/),chunks=[];for(let i=0;i<sentences.length;i+=2)chunks.push(sentences.slice(i,i+2).join(' '));return chunks}).map(p=>`<p>${esc(p)}</p>`).join('');
let D,SLIDES,section=0,view='teach',session=null,lesson=null,storageOK=true;
let progress={cards:{},lessons:{},xp:0,days:[]};
try{const p=JSON.parse(localStorage.getItem(KEY464));if(p&&p.cards&&typeof p.cards==='object'&&!Array.isArray(p.cards)&&typeof p.xp==='number'&&Array.isArray(p.days))progress={...progress,...p,lessons:p.lessons||{}}}catch{storageOK=false}
function save(){try{localStorage.setItem(KEY464,JSON.stringify(progress))}catch{storageOK=false}stats()}
function stats(){$('#stats').innerHTML=`<span>✦ ${progress.xp} XP</span><span>${progress.days.length} study day${progress.days.length===1?'':'s'}</span>`;$('#storage-status').textContent=storageOK?'CIS 464 progress saves separately in this browser.':'Browser storage is unavailable. Progress will last only for this visit.'}
function record(x,ok){const old=progress.cards[x.id]||{seen:0,level:0};const level=ok?Math.min(6,old.level+1):0;progress.cards[x.id]={seen:old.seen+1,level,completed:old.completed||ok,due:Date.now()+(ok?[1,3,7,14,30,60][level-1]*86400000:60000)};progress.xp+=ok?10:2;const day=new Date().toLocaleDateString('en-CA');if(!progress.days.includes(day))progress.days.push(day);save()}
const filtered=items=>section?items.filter(x=>x.section===section):items;
const completed=x=>!!progress.cards[x.id]?.completed;
const sec=id=>D.sections.find(s=>s.id===id);
const source=x=>x.number?x:D.questions.find(q=>q.number===x.source);
const label=x=>`Chapter ${x.section} · ${sec(x.section).title}`;
function sources(x){const q=source(x);if(!q)return '';return `<details class="question-source"><summary>Source & chapter connection</summary><p>Schwalbe Chapter ${q.section}, slide${q.slides.length===1?'':'s'} ${q.slides.join(', ')}.</p><p class="source-note">Explanation and practice authored from your supplied slides, with linked clarifications where needed. These are study aids, not an instructor-issued answer key.</p>${D.references.filter(r=>r.questions.includes(q.number)).map(r=>`<p><a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title)}</a></p>`).join('')}<button data-source-chapter="${q.section}" data-source-slide="${q.slides[0]}">See source slide material</button></details>`}
function picker(){return `<label class="tiny">Chapter <select id="section"><option value="0">All topics</option>${D.sections.map(s=>`<option value="${s.id}" ${s.id===section?'selected':''}>${s.title}</option>`).join('')}</select></label>`}
function heading(t,p){return `<div class="heading"><div><div class="eyebrow">CIS 464 / PROJECT MANAGEMENT</div><h1>${esc(t)}</h1><p class="muted">${esc(p)}</p></div>${picker()}</div>`}
const navs=[['teach','☀','Learn First'],['practice','◈','Practice'],['flash','▤','Flashcards'],['map','▧','See the connections'],['exam','✓','Practice exam']];
const focused=[['apply','◎','Apply your knowledge'],['sort','≋','Sorting & sequences'],['abbrev','⌁','Abbreviations'],['math','#','Financial lab']];
const reference=[['terms','Aa','Terms & definitions'],['guide','☷','Complete study reference'],['readings','↗','Slides & sources']];
function buttonNav([id,icon,title]){return `<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon} &nbsp; ${title}</button>`}
function chrome(){stats();$('#nav').innerHTML=navs.map(buttonNav).join('')+`<details ${focused.some(x=>x[0]===view)?'open':''}><summary>Focused practice</summary>${focused.map(buttonNav).join('')}</details><details ${reference.some(x=>x[0]===view)?'open':''}><summary>Reference library</summary>${reference.map(buttonNav).join('')}</details>`;$('#modebar').innerHTML=`<button data-view="teach" class="${view==='teach'?'active':''}">Learn First</button><button data-view="practice" class="${view==='practice'?'active':''}">Practice Quiz</button><span class="tiny muted">CIS 464 · Chapters 1, 2, 3 & 10</span>`}
function navigate(v){view=v;session=null;lesson=null;render();window.scrollTo(0,0)}
function render(){chrome();const fn={teach:teachHome,practice:practiceHome,flash:flashHome,map:mapHome,exam:examHome,apply:applyHome,sort:sortHome,abbrev:abbrevHome,math:mathHome,terms:termsHome,guide:guideHome,readings:readingsHome}[view];fn();const p=$('#section');if(p)p.onchange=()=>{section=+p.value;render()}}
function teachHome(){const sections=section?D.sections.filter(s=>s.id===section):D.sections;$('#app').innerHTML=heading('Understand it before you memorize it.','Start with a plain explanation, see a concrete example, then practice. Each lesson connects to its chapter and source slides.')+`<div class="notice">Your four slide decks set the scope. Lessons are organized by Chapters 1, 2, 3, and 10. The slide library retains all 183 slides, including diagrams, images, and classroom prompts.</div>`+sections.map(s=>{const qs=D.questions.filter(q=>q.section===s.id),done=qs.filter(q=>progress.lessons[q.id]).length;return `<section class="card" style="margin-top:22px"><span class="tag">${esc(s.reading)}</span><h2>Chapter ${s.id} · ${esc(s.title)}</h2><p>${esc(s.intro)}</p><div class="bar"><span style="width:${100*done/qs.length}%"></span></div><p class="tiny">${done} / ${qs.length} lessons completed</p><div class="lesson-list">${qs.map(q=>`<button data-lesson="${q.number}"><span class="badge">${q.number}</span><span class="lesson-label">${esc(q.title)}<small>${esc(q.q)}</small></span><span aria-label="${progress.lessons[q.id]?'Completed':'Not completed'}">${progress.lessons[q.id]?'✓':'→'}</span></button>`).join('')}</div></section>`}).join('')}
function openLesson(number,step=0){view='teach';session=null;lesson={number,step};chrome();const q=D.questions.find(q=>q.number===number);const steps=['Start with the idea','The complete answer','A concrete example'];$('#app').innerHTML=`<div class="study"><div class="row spread"><span class="tag">${label(q)} · Lesson ${q.number} / ${D.questions.length}</span><button data-view="teach">All lessons</button></div><h1>${esc(q.title)}</h1><div class="bar"><span style="width:${100*(step+1)/3}%"></span></div><section class="card lesson-copy" style="margin-top:24px"><p class="lesson-step-label">STEP ${step+1} OF 3 · ${steps[step]}</p><h2>${esc(step===1?q.q:steps[step])}</h2>${paragraphs([q.teach,q.answer,q.example][step])}${step===2?`<div class="notice">Remember the connection: ${esc(q.correct)}</div>`:''}${sources(q)}</section><div class="actions">${step?'<button id="lesson-prev">← Back</button>':''}${step<2?'<button class="primary" id="lesson-next">Next step →</button>':`<button class="primary" id="lesson-practice">Try this topic →</button><button id="lesson-complete">${progress.lessons[q.id]?'✓ Lesson completed':'Mark lesson read'}</button>`}</div>${[30,31,32,33,34,35].includes(number)?'<p><button data-view="math">Open the step-by-step financial lab</button></p>':''}</div>`;if($('#lesson-prev'))$('#lesson-prev').onclick=()=>openLesson(number,step-1);if($('#lesson-next'))$('#lesson-next').onclick=()=>openLesson(number,step+1);if($('#lesson-complete'))$('#lesson-complete').onclick=()=>{progress.lessons[q.id]=true;save();openLesson(number,2)};if($('#lesson-practice'))$('#lesson-practice').onclick=()=>{progress.lessons[q.id]=true;save();start('practice',[q,...D.checks.filter(c=>c.source===number)],number)};$('#app').focus()}
function sectionCards(){return `<div class="grid">${D.sections.map(s=>{const qs=D.questions.filter(q=>q.section===s.id),done=qs.filter(completed).length;return `<section class="card"><span class="tag">${esc(s.reading)}</span><h2>${esc(s.title)}</h2><div class="bar"><span style="width:${100*done/qs.length}%"></span></div><p>${done} / ${qs.length} lesson checks answered correctly${done===qs.length?' · ✓ Complete':''}</p><div class="actions"><button class="primary" data-practice-section="${s.id}">Practice this section</button></div></section>`}).join('')}</div>`}
function practiceHome(){const pool=filtered(D.questions),done=pool.filter(completed).length;$('#app').innerHTML=heading('Practice the chapters','Choose answers—no written responses required. Missed questions return later until you get them right.')+`<section class="focus"><div><h2>${done} of ${pool.length} lesson checks completed</h2><p>One correct answer fills that prompt’s completion credit. Extra practice and vocabulary are tracked separately.</p><div class="actions"><button class="primary" id="quick">Review 10</button><button id="all-guide">Practice all ${pool.length}</button><button id="mixed-topic">Mix in terms & activities</button></div></div><div class="ring">${Math.round(100*done/pool.length)}%<small>COMPLETED</small></div></section>`+sectionCards()+`<div class="notice">The full answer after each question covers all parts of the slide topic. For smaller checks on individual details, use Apply your knowledge. Completion shows practice done, not a guarantee of exam readiness.</div>`;$('#quick').onclick=()=>{const rank=x=>{const p=progress.cards[x.id];return p?.level===0?0:!p?1:p.due<=Date.now()?2:3};start('practice',shuffle(pool).sort((a,b)=>rank(a)-rank(b)).slice(0,10))};$('#all-guide').onclick=()=>start('practice',shuffle(pool));$('#mixed-topic').onclick=()=>start('practice',shuffle(filtered(mixedPool())).slice(0,20))}
function mixedPool(){return [...D.questions,...D.vocab,...D.cloze,...D.sorts.map(x=>({...x,kind:'sort'})),...D.vocab.filter(x=>x.exp).map(x=>({...x,id:x.id+'-build',kind:'wordbank',q:`Build the full name of ${x.term}`}))]}
function prepare(x){if(x.kind==='sort')return {...x,current:shuffledOrder(x.items)};if(x.kind==='wordbank')return {...x,bank:shuffledOrder(x.exp.split(/\s+/).map((word,i)=>({word,i}))),picked:[]};return {...x,options:shuffle([x.correct,...x.distractors])}}
function start(mode,items,lessonNumber=null){if(!items.length){$('#app').innerHTML='<section class="card"><h2>No items in this selection</h2><button data-view="practice">Choose another topic</button></section>';return}session={mode,items:items.map(prepare),index:0,total:items.length,cleared:new Set(),first:{},right:0,graded:false,revealed:false,lessonNumber};renderSession();window.scrollTo(0,0)}
function preteach(x){const q=source(x);return `<details class="card"><summary>Teach me first · show the rule</summary><div class="lesson-copy">${paragraphs(x.teach)}${q?`<p><strong>Example:</strong> ${esc(x.example||q.example)}</p>`:''}</div></details>`}
function feedback(x,ok){const q=source(x);return `<div class="feedback" role="status"><strong>${ok?'✓ Correct':'Not quite — let’s make it simple'}</strong><h3>${x.kind==='sort'?'Correct order':x.kind==='wordbank'?'Full name':'Correct answer'}</h3>${paragraphs(x.kind==='sort'?x.items.join(' → '):x.kind==='wordbank'?x.exp:x.correct)}<h3>Why this fits</h3>${paragraphs(x.teach)}${q?`<h3>Picture the action</h3>${paragraphs(x.example||q.example)}<details><summary>Read the complete chapter explanation</summary>${paragraphs(q.answer)}</details>`:''}${sources(x)}</div>`}
function sessionHeader(x){const s=session;return `<div class="study"><div class="row spread"><span class="tag">${label(x)}</span><button data-view="${s.mode==='flash'?'flash':s.mode==='exam'?'exam':'practice'}">End session</button></div><p class="tiny">${s.mode==='exam'?'Exam':s.mode==='flash'?'Flashcards':'Practice'} · ${Math.min(s.index+1,s.items.length)} / ${s.items.length}${s.mode!=='exam'&&s.mode!=='flash'?` · ${s.cleared.size}/${s.total} cleared`:''}</p><div class="bar"><span style="width:${100*(s.mode==='exam'?s.index:s.cleared.size)/s.total}%"></span></div>`}
function renderSession(){const s=session;if(!s||s.index>=s.items.length){finish();return}chrome();const x=s.items[s.index];s.graded=false;s.revealed=false;if(s.mode==='flash'){renderFlash(x);return}if(x.kind==='sort'){renderSort(x);return}if(x.kind==='wordbank'){renderWordBank(x);return}$('#app').innerHTML=sessionHeader(x)+`<h2 class="question">${esc(x.q)}</h2>${s.mode==='exam'?'':preteach(x)}<p class="eyebrow">CHOOSE ONE ANSWER</p><div class="choices">${x.options.map((o,i)=>`<button data-option="${i}"><b>${String.fromCharCode(65+i)}.</b><span>${esc(o)}</span></button>`).join('')}</div><div id="feedback"></div></div>`;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{if(s.graded)return;const answer=x.options[+b.dataset.option];document.querySelectorAll('[data-option]').forEach(btn=>{btn.disabled=true;if(x.options[+btn.dataset.option]===x.correct)btn.classList.add('correct')});if(answer!==x.correct)b.classList.add('wrong');grade(x,answer===x.correct,answer)})}
function grade(x,ok,selected){const s=session;if(s.graded)return;s.graded=true;s.lastOK=ok;if(!(x.id in s.first)){s.first[x.id]={ok,selected};if(ok)s.right++}if(ok)s.cleared.add(x.id);record(x,ok);$('#feedback').innerHTML=feedback(x,ok)+`<button class="primary" id="next">${s.index+1===s.items.length&&(ok||s.mode==='exam')?'See results':'Continue →'}</button>`;$('#next').onclick=advance}
function advance(){const s=session,x=s.items[s.index];if(!s.lastOK&&s.mode!=='exam')s.items.splice(Math.min(s.index+4,s.items.length),0,prepare(x));s.index++;renderSession();$('#app').focus()}
function finish(){const s=session;if(!s)return;const missed=Object.entries(s.first).filter(([,v])=>!v.ok).map(([id])=>s.items.find(x=>x.id===id));$('#app').innerHTML=`<div class="study"><section class="card"><div class="eyebrow">CIS 464 · SESSION COMPLETE</div><h1>${s.mode==='exam'?`${s.right} / ${s.total} on first attempts`:s.mode==='flash'?'Recall round completed':'Every item cleared ✓'}</h1><p>${s.mode==='exam'?'Your score uses your first answer to each question. Review missed topics below.':`You answered or recalled all ${s.total} items successfully, including any retries.`}</p><p>${missed.length} item${missed.length===1?'':'s'} needed another look on the first attempt.</p><div class="actions"><button class="primary" data-view="practice">Back to practice</button>${missed.length?'<button id="retry-missed">Practice missed items</button>':''}${s.lessonNumber?`<button data-lesson="${s.lessonNumber}">Return to the lesson</button>`:''}</div></section>${s.mode==='exam'?missed.map(x=>`<details class="card exam-review"><summary>${esc(x.q)}</summary>${feedback(x,false)}</details>`).join(''):''}</div>`;if($('#retry-missed'))$('#retry-missed').onclick=()=>start('practice',shuffle(missed))}
function flashHome(){$('#app').innerHTML=heading('Flip, remember, repeat','Think of the answer, then tap the card. Mark honestly: remembered cards earn completion credit, and missed cards come back.')+`<div class="grid"><section class="card"><h2>Chapter flashcards</h2><p>${filtered(D.questions).length} slide topics with complete answers.</p><button class="primary" id="flash-guide">Study chapter cards</button></section><section class="card"><h2>Vocabulary flashcards</h2><p>${filtered(D.vocab).length} terms, including full abbreviation names.</p><button class="primary" id="flash-vocab">Study terms</button></section></div>`;$('#flash-guide').onclick=()=>start('flash',shuffle(filtered(D.questions)));$('#flash-vocab').onclick=()=>start('flash',shuffle(filtered(D.vocab)))}
function renderFlash(x){const s=session;$('#app').innerHTML=sessionHeader(x)+`<p class="eyebrow" id="flash-side">FRONT · TAP TO REVEAL</p><button class="card flashcard" id="flip" aria-label="Reveal answer"><h2>${esc(x.term||x.q)}</h2></button><div id="rating"></div></div>`;$('#flip').onclick=()=>{s.revealed=!s.revealed;$('#flash-side').textContent=s.revealed?'BACK · TAP TO HIDE':'FRONT · TAP TO REVEAL';$('#flip').setAttribute('aria-label',s.revealed?'Hide answer':'Reveal answer');$('#flip').innerHTML=s.revealed?`${x.exp?`<h2>${esc(x.exp)}</h2>`:''}${paragraphs(x.answer)}`:`<h2>${esc(x.term||x.q)}</h2>`;$('#rating').innerHTML=s.revealed?`<div class="actions"><button id="forgot">Still learning · show again</button><button class="primary" id="remembered">I remembered it</button></div><details><summary>Help me understand</summary>${paragraphs(x.teach)}</details>`:'';if(s.revealed){$('#forgot').onclick=()=>rate(false);$('#remembered').onclick=()=>rate(true)}};function rate(ok){if(s.graded)return;s.graded=true;s.lastOK=ok;if(!(x.id in s.first)){s.first[x.id]={ok};if(ok)s.right++}if(ok)s.cleared.add(x.id);record(x,ok);advance()}}
function applyHome(){$('#app').innerHTML=heading('Apply your knowledge','Extra checks on the same chapter topics, kept separate from the slide topics.')+`<section class="card"><h2>${filtered(D.checks).length} focused checks</h2><p>Recognize examples, distinguish similar terms, and test individual parts of multi-part chapter questions.</p><button class="primary" id="apply-start">Practice these checks</button><button id="cloze-start">Fill-in-the-blank choices</button></section>`;$('#apply-start').onclick=()=>start('practice',shuffle(filtered(D.checks)));$('#cloze-start').onclick=()=>start('practice',shuffle(filtered(D.cloze)))}
function sortHome(){$('#app').innerHTML=heading('Put the steps in order','Every attempt starts shuffled. These are specific example sequences, not a claim that every business uses identical steps.')+`<div class="grid">${filtered(D.sorts).map(x=>`<section class="card"><h2>${esc(x.q)}</h2><p>${label(x)}</p><button class="primary" data-sort="${x.id}">Build this sequence</button></section>`).join('')}</div>${filtered(D.sorts).length?'':'<p>No sequence activities in this section. Select All topics to see them.</p>'}`}
function renderSort(x){$('#app').innerHTML=sessionHeader(x)+`<h2>${esc(x.q)}</h2>${preteach(x)}<div class="order">${x.current.map((v,i)=>`<div><b>${i+1}</b><span>${esc(v)}</span><button data-move="${i}" data-delta="-1" aria-label="Move ${esc(v)} up" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-delta="1" aria-label="Move ${esc(v)} down" ${i===x.current.length-1?'disabled':''}>↓</button></div>`).join('')}</div><button class="primary" id="check-order">Check order</button><div id="feedback"></div></div>`;document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const i=+b.dataset.move,j=i+(+b.dataset.delta);[x.current[i],x.current[j]]=[x.current[j],x.current[i]];renderSort(x)});$('#check-order').onclick=()=>{if(session.graded)return;document.querySelectorAll('[data-move],#check-order').forEach(b=>b.disabled=true);grade(x,x.current.every((v,i)=>v===x.items[i]))}}
function abbrevHome(){const items=filtered(D.vocab).filter(v=>v.exp);$('#app').innerHTML=heading('Abbreviations, fully understood','Choose the name or build it one word at a time. Then connect it to what it actually means.')+`<section class="card"><h2>${items.length} abbreviations</h2><p>${items.map(v=>esc(v.term)).join(' · ')}</p><div class="actions"><button class="primary" id="abbrev-choice">Choose the full name</button><button id="abbrev-build">Build with a word bank</button></div></section>`;$('#abbrev-choice').onclick=()=>start('practice',shuffle(items.map(v=>({...v,id:v.id+'-name',q:`In this CIS 464 course, what does ${v.term} stand for?`,correct:v.exp,distractors:D.abbreviationDistractors[v.term]}))));$('#abbrev-build').onclick=()=>start('practice',shuffle(items.map(v=>({...v,id:v.id+'-build',kind:'wordbank',q:`Build the full name of ${v.term}`}))))}
function renderWordBank(x){$('#app').innerHTML=sessionHeader(x)+`<h2>${esc(x.q)}</h2><p>Tap words in order. Tap a selected word to return it to the bank.</p><div class="word-answer"><div class="wordbank">${x.picked.map((v,i)=>`<button data-remove="${i}">${esc(v.word)} ×</button>`).join('')||'<span class="muted">Your answer will appear here</span>'}</div></div><div class="wordbank">${x.bank.map(v=>`<button data-word="${v.i}" ${x.picked.some(w=>w.i===v.i)?'disabled':''}>${esc(v.word)}</button>`).join('')}</div><button class="primary" id="check-bank" ${x.picked.length!==x.bank.length?'disabled':''}>Check name</button><div id="feedback"></div></div>`;document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{x.picked.push(x.bank.find(w=>w.i===+b.dataset.word));renderWordBank(x)});document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{x.picked.splice(+b.dataset.remove,1);renderWordBank(x)});$('#check-bank').onclick=()=>{if(session.graded)return;document.querySelectorAll('[data-word],[data-remove],#check-bank').forEach(b=>b.disabled=true);grade(x,x.picked.map(v=>v.word).join(' ')===x.exp)}}
function termsHome(){$('#app').innerHTML=heading('Words you can actually understand','Definitions are tied to the same chapter topics. Open the related lesson for context.')+`<label class="search-label">Find a term<input type="search" id="search" placeholder="Try: input, enterprise, ERP…"></label><div class="wordlist" id="terms"></div>`;function update(){const str=$('#search').value.toLowerCase(),vs=filtered(D.vocab).filter(v=>(v.term+' '+v.exp+' '+v.answer).toLowerCase().includes(str));$('#terms').innerHTML=vs.map(v=>`<article><span class="tag">${label(v)}</span><h3>${esc(v.term)}${v.exp?' · '+esc(v.exp):''}</h3>${paragraphs(v.answer)}${paragraphs(v.teach)}<button data-lesson="${v.source}">See it in context</button></article>`).join('')||'<p>No matching terms.</p>'}$('#search').oninput=update;update()}
function guideHome(){$('#app').innerHTML=heading('Your complete chapter reference','Every lesson has its full explanation, a concrete example, and slide references. Use Slides & sources for all original slide material.')+`<div class="notice">${filtered(D.questions).length} of ${D.questions.length} lesson topics shown. Chapter 2 formulas keep money amounts, ratios, timing conventions, and rounding separate. Chapter 10 distinguishes course examples and forecasts from established definitions.</div><div class="lesson-list">${filtered(D.questions).map(q=>`<article class="card"><span class="tag">${label(q)}</span><h3>${esc(q.title)}</h3><details><summary>${esc(q.q)}</summary><div class="lesson-copy">${paragraphs(q.answer)}<h3>Let’s make it simple</h3>${paragraphs(q.teach)}<h3>Example</h3>${paragraphs(q.example)}</div>${sources(q)}<div class="actions"><button data-lesson="${q.number}">Teach me step by step</button><button data-question="${q.number}">Practice this topic</button></div></details></article>`).join('')}</div>`}
function examHome(){$('#app').innerHTML=heading('Practice exam','A new shuffled exam each time. First choices count toward the score; explanations appear after each answer.')+`<section class="card"><h2>Choose your practice</h2><div class="row"><label>Bank <select id="bank"><option value="guide">Original study-lesson checks</option><option value="mixed">Guide + detailed understanding checks</option><option value="terms">Vocabulary</option></select></label><label>Length <select id="length"><option value="10">10</option><option value="20" selected>20</option><option value="9999">Entire selected bank</option></select></label></div><p>Missed items can be practiced again after the exam. No pre-answer explanation is shown in exam mode.</p><button class="primary" id="exam-start">Generate exam</button></section>`;$('#exam-start').onclick=()=>{const b=$('#bank').value;start('exam',shuffle(filtered(b==='guide'?D.questions:b==='terms'?D.vocab:[...D.questions,...D.checks])).slice(0,+$('#length').value))}}
// Only CIS 464 financial concepts appear here. No other class's numeric rules are loaded.
const money=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2});
const pct=n=>(n*100).toFixed(2)+'%';
let financial=null,financeStep=0,financeRound=0;
function financePreset(which){if(which==='exercise')return {name:'Chapter 2 · Slide 28 exercise',rate:.07,costs:[300000,40000,40000,40000],benefits:[0,120000,120000,120000],offset:1,rounded:false,source:35};if(which==='figure')return {name:'Chapter 2 · Slide 29 worked figure',rate:.08,costs:[140000,40000,40000,40000],benefits:[0,200000,200000,200000],offset:0,rounded:true,source:33};return randomFinance(financial)}
function randomFinance(previous){let c;do{const initial=(5+Math.floor(Math.random()*16))*10000,annual=(1+Math.floor(Math.random()*5))*10000,benefit=(4+Math.floor(Math.random()*18))*10000;c={name:'Fresh financial practice',rate:[.05,.07,.08,.10,.12][Math.floor(Math.random()*5)],costs:[initial,annual,annual,annual],benefits:[0,benefit,benefit,benefit],offset:0,rounded:false,source:32}}while(previous&&JSON.stringify([c.rate,c.costs,c.benefits])===JSON.stringify([previous.rate,previous.costs,previous.benefits]));return c}
function financialResult(c){let cumulative=0,rawCumulative=0;const rows=c.costs.map((cost,i)=>{const t=i+c.offset,factor=c.rounded?Math.round(100/(1+c.rate)**t)/100:1/(1+c.rate)**t,pvc=cost*factor,pvb=c.benefits[i]*factor,net=pvb-pvc;const previous=cumulative;cumulative+=net;rawCumulative+=c.benefits[i]-cost;return {t,cost,benefit:c.benefits[i],factor,pvc,pvb,net,cumulative,rawCumulative,previous}});const pvc=rows.reduce((s,r)=>s+r.pvc,0),pvb=rows.reduce((s,r)=>s+r.pvb,0),cost=rows.reduce((s,r)=>s+r.cost,0),benefit=rows.reduce((s,r)=>s+r.benefit,0);return {rows,pvc,pvb,npv:pvb-pvc,roi:(pvb-pvc)/pvc,rawROI:(benefit-cost)/cost,payback:rows.find(r=>r.cumulative>=0)?.t??null,rawPayback:rows.find(r=>r.rawCumulative>=0)?.t??null}}
function mathHome(){if(!financial)financial=financePreset('exercise');const c=financial;financeStep=0;$('#app').innerHTML=heading('Financial lab','Chapter 2 · Follow each calculation, then practice with new values. No typed answers needed.')+`<details class="card" open><summary>Formulas and what the words mean</summary><div class="lesson-copy"><p><b>Cost</b> = resources paid for. <b>Benefit</b> = value received, expressed in money for this calculation. <b>Net</b> = benefit minus cost.</p><p><b>PV = cash flow ÷ (1 + r)<sup>t</sup></b>. Use r as a decimal (7% = 0.07). The exponent t is how many periods from now. At t = 0, the factor is 1.</p><p><b>NPV = total PV benefits − total PV costs.</b> It is a money amount.</p><p><b>Discounted ROI = NPV ÷ total PV costs × 100%.</b> Simple ROI uses undiscounted totals instead. Both conventions are labeled here.</p><p><b>Payback</b> occurs when cumulative net cash flow reaches zero. Cumulative means adding each period to the previous total. State whether you are discounting.</p><p><b>Weighted score = Σ(weight × rating).</b> The Σ sign means add the products. Weights must sum to 1 (or 100%).</p></div></details><section class="card" style="margin-top:22px"><div class="actions"><button id="exercise">Slide 28 exercise</button><button id="figure">Slide 29 worked figure</button><button id="fresh">New numbers</button><button id="weighted">Weighted scoring</button></div><h2 style="margin-top:24px">${esc(c.name)}</h2><p>Discount rate: <b>${pct(c.rate)}</b>. First listed cash flow is ${c.offset===0?'at time zero (today)':'at the end of Year 1'}. Cash flows below are at period endpoints.</p><div class="actions"><button id="timing">Switch first cash flow to ${c.offset===0?'year-end 1':'time zero'}</button><button id="rounding">${c.rounded?'Use full-precision discount factors':'Use slide-style factors rounded to 2 decimals'}</button></div><p class="source-note">Slide 28 labels Y1–Y4 without explicitly fixing within-year timing; both conventions are available. Slide 29 explicitly starts at Year 0 and rounds factors to 0.93, 0.86, and 0.79. Rounding factors early changes totals. This lab labels the method instead of treating differing results as interchangeable.</p><div class="note-table"><table><thead><tr><th>Time t</th><th>Cost</th><th>Benefit</th><th>Raw net</th></tr></thead><tbody>${c.costs.map((cost,i)=>`<tr><td>${i+c.offset}</td><td>${money(cost)}</td><td>${money(c.benefits[i])}</td><td>${money(c.benefits[i]-cost)}</td></tr>`).join('')}</tbody></table></div><div id="math-work" class="formula-steps"></div><div class="actions"><button class="primary" id="finance-next">Show step 1</button><button id="finance-practice">Practice a fresh set</button></div></section>`;$('#exercise').onclick=()=>{financial=financePreset('exercise');mathHome()};$('#figure').onclick=()=>{financial=financePreset('figure');mathHome()};$('#fresh').onclick=()=>{financial=randomFinance(c);mathHome()};$('#timing').onclick=()=>{financial={...c,offset:c.offset===0?1:0};mathHome()};$('#rounding').onclick=()=>{financial={...c,rounded:!c.rounded};mathHome()};$('#finance-next').onclick=showFinanceStep;$('#finance-practice').onclick=()=>{financial=randomFinance(c);start('practice',financeQuestions(financial))};$('#weighted').onclick=weightedLab}
function showFinanceStep(){const c=financial,r=financialResult(c);const steps=[`<h3>1 · Translate time and rate into a factor</h3><p>r = ${c.rate}. For each period, the discount factor is 1 ÷ (1 + ${c.rate})<sup>t</sup>. ${c.rounded?'Round each factor to two decimals to reproduce the slide-style method.':'Keep full precision during calculation; displayed amounts are rounded to cents.'}</p><p>${r.rows.map(x=>`t=${x.t}: factor ${x.factor.toFixed(c.rounded?2:5)}`).join(' · ')}</p>`,`<h3>2 · Discount costs and benefits separately</h3><p>PV cost = cost × factor. PV benefit = benefit × factor.</p><div class="note-table"><table><thead><tr><th>t</th><th>PV cost</th><th>PV benefit</th><th>PV net</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${x.t}</td><td>${money(x.pvc)}</td><td>${money(x.pvb)}</td><td>${money(x.net)}</td></tr>`).join('')}</tbody></table></div>`,`<h3>3 · Add and subtract for NPV</h3><p>Total PV benefits ${money(r.pvb)} − total PV costs ${money(r.pvc)} = <b>${money(r.npv)}</b>.</p><p>${r.npv>0?'Positive: modeled benefits exceed modeled costs in present-value terms.':r.npv<0?'Negative: modeled benefits do not recover modeled costs in present-value terms.':'Zero: modeled benefits and costs are equal in present-value terms.'} This financial measure is one part of selection, alongside strategy, risk, and requirements.</p>`,`<h3>4 · Divide net return by cost for ROI</h3><p>Discounted ROI = ${money(r.npv)} ÷ ${money(r.pvc)} × 100% = <b>${pct(r.roi)}</b>.</p><p>Using raw totals instead gives simple ROI <b>${pct(r.rawROI)}</b>. They differ because only the first calculation accounts for cash-flow timing.</p>`,`<h3>5 · Follow cumulative totals for payback</h3><p>Discounted cumulative net by period: ${r.rows.map(x=>`t=${x.t}: ${money(x.cumulative)}`).join(' → ')}.</p><p>${r.payback===null?'No discounted payback within the stated horizon.':`The first nonnegative period-end total is at t=${r.payback}.`}</p><p>Raw payback: ${r.rawPayback===null?'not reached within the stated horizon':`first nonnegative period-end total at t=${r.rawPayback}`}. Fractional-year payback requires an additional assumption about when cash is earned within the year; it is not implied by these endpoint cash flows.</p>`];if(financeStep>=steps.length)return;$('#math-work').insertAdjacentHTML('beforeend',`<article class="formula-step">${steps[financeStep++]}</article>`);$('#finance-next').textContent=financeStep===steps.length?'All steps shown':`Show step ${financeStep+1} →`;$('#finance-next').disabled=financeStep===steps.length}
function financeQuestions(c){const r=financialResult(c),serial=JSON.stringify([c.costs,c.benefits,c.rate,c.offset,c.rounded]);const scenario=`Costs: ${c.costs.map(money).join(', ')}. Benefits: ${c.benefits.map(money).join(', ')}. Rate ${pct(c.rate)}; first flow at t=${c.offset}; ${c.rounded?'factors rounded to 2 decimals':'full-precision factors'}.`;const answer=money(r.npv),roi=pct(r.roi);return [
{source:31,q:'At t = 0, what is the discount factor?',correct:'1',distractors:['0',String(1+c.rate),String(c.rate)],teach:'Any positive base raised to power zero is 1. A time-zero cash flow is already in present-value terms.',example:'At time zero, a $100 cost has a present value of $100.'},
{source:32,q:scenario+' What is NPV?',correct:answer,distractors:[money(r.pvb),money(r.pvc),money(r.npv+Math.max(1000,r.pvc*.1))],teach:`Add PV benefits (${money(r.pvb)}) and subtract PV costs (${money(r.pvc)}). NPV is ${answer}. Gross benefits and total costs are not the net result.`,example:scenario},
{source:33,q:scenario+' What is discounted ROI?',correct:roi,distractors:[pct(r.roi+1),pct(r.roi+.1),pct(r.roi-.1)],teach:`Divide NPV ${money(r.npv)} by PV costs ${money(r.pvc)}, then multiply by 100: ${roi}. Do not divide by benefits or omit the subtraction.`,example:scenario},
{source:34,q:scenario+' When is the first nonnegative discounted cumulative total?',correct:r.payback===null?'Not within the stated horizon':`At period end t=${r.payback}`,distractors:(r.payback===null?[0,1,2].map(t=>`At period end t=${t}`):['Not within the stated horizon',...r.rows.filter(x=>x.t!==r.payback).slice(0,2).map(x=>`At period end t=${x.t}`)]),teach:`Discounted cumulative totals are ${r.rows.map(x=>money(x.cumulative)).join(' → ')}. ${r.payback===null?'None reaches zero.':'Use the first nonnegative total, not merely the first positive annual cash flow.'}`,example:scenario}
].map((x,i)=>({...x,id:`464-finance-${serial}-${i}`,section:2,answer:x.correct}))}
function weightedLab(){const weights=[.1,.6,.3],ratings=[1,10,5];$('#app').innerHTML=heading('Build the weighted score','Chapter 2 · Slide 25: eligibility first, then weighted comparison.')+`<section class="card"><p>The example uses Low = 1, Medium = 5, High = 10. These are the course’s example ratings, not universal numerical meanings.</p><div class="note-table"><table><thead><tr><th>Criterion</th><th>Weight</th><th>Rating</th><th>Contribution</th></tr></thead><tbody>${weights.map((w,i)=>`<tr><td>${i+1}</td><td>${w}</td><td><select aria-label="Rating for criterion ${i+1}" data-rating="${i}">${[1,5,10].map(v=>`<option value="${v}" ${v===ratings[i]?'selected':''}>${v}</option>`).join('')}</select></td><td id="weight-${i}"></td></tr>`).join('')}</tbody></table></div><div class="notice" id="weighted-result" aria-live="polite"></div><button data-view="math">Back to financial lab</button></section>`;function update(){const products=weights.map((w,i)=>w*ratings[i]);products.forEach((v,i)=>$('#weight-'+i).textContent=`${weights[i]} × ${ratings[i]} = ${v.toFixed(2)}`);$('#weighted-result').textContent=`Weights sum to 1.00. Add contributions: ${products.map(x=>x.toFixed(2)).join(' + ')} = ${products.reduce((s,x)=>s+x,0).toFixed(2)}.`}document.querySelectorAll('[data-rating]').forEach(b=>b.onchange=()=>{ratings[+b.dataset.rating]=+b.value;update()});update()}
const mapViews={
constraints:{title:'The project balancing act',intro:'Select a constraint to see how it connects to the others. These are project constraints, not networking or enterprise architecture layers.',parts:[['Scope','What is included?','Adding a feature adds work. Check its effects on time, cost, quality, resources, and risk before approving it.',5],['Schedule','When must it happen?','A shorter deadline may require more resources or less scope. Simply demanding speed can harm quality.',5],['Cost','What can we spend?','A fixed budget limits resources. Evaluate alternatives instead of promising unlimited work for the same money.',5],['Quality','How well must it work?','A fast, inexpensive result that does not meet requirements may not create value. Build quality into the work.',5]]},
work:{title:'Project, program, portfolio',intro:'These are management relationships. A portfolio can contain projects directly as well as programs; its work need not all be related.',parts:[['Portfolio','Choose the strategic mix','The organization balances investments, priorities, risk, and available resources across its work.',14],['Program','Coordinate related benefits','A campus transformation program coordinates related identity, registration, and student-service projects.',14],['Project','Deliver a specific result','A particular registration replacement has its own objectives, team, temporary life, and deliverables.',14],['Operations','Run and support the result','Once delivered, the service needs monitoring, support, and maintenance. Later projects may improve it.',7]]},
documents:{title:'Which document does what?',intro:'The documents connect, but are not interchangeable. Select a document before trying a scenario.',parts:[['Business case','Why invest?','Compare needs, alternatives, costs, benefits, risks, and recommendation.',42],['Charter','Who authorizes it?','An authorized sponsor formally approves the project and establishes high-level direction and authority.',43],['PM plan','How will we manage it?','Coordinate execution, monitoring, control, closure, and approved baselines.',44],['Register & engagement plan','Who matters, and how do we work with them?','The register identifies and assesses stakeholders. The engagement plan sets strategies and communications.',46]]},
ai:{title:'AI agent distinctions',intro:'These categories highlight different capabilities and can overlap. An internal model does not automatically mean learning.',parts:[['Simple reflex','React to the current condition','Uses predefined condition–action rules. Example: turn heat on below a threshold.',59],['Model-based reflex','Track internal state','Uses a model and remembered state to handle incomplete current observations.',60],['Goal-based','Choose a path to a goal','Selects actions according to whether they help achieve a desired state.',61],['Utility-based','Compare desirable outcomes','Weighs alternatives according to a value measure, such as balancing time and fuel.',62],['Learning','Improve with experience','Changes behavior through feedback or experience; can be combined with other capabilities.',63]]}
};
function mapHome(selected='constraints'){const m=mapViews[selected];$('#app').innerHTML=heading('See the connections','Project concepts explained through connected examples.')+`<div class="actions">${Object.entries(mapViews).map(([k,v])=>`<button data-map="${k}" aria-pressed="${k===selected}">${esc(v.title)}</button>`).join('')}<button id="grid-map">Power–interest grid</button></div><section class="card" style="margin-top:24px"><h2>${m.title}</h2><p>${m.intro}</p><div class="map-stack">${m.parts.map((p,i)=>`<button data-map-part="${i}" aria-pressed="${i===0}"><b>${esc(p[0])}</b> · ${esc(p[1])}</button>`).join('')}</div><div class="notice" id="map-detail" aria-live="polite"></div></section>`;function detail(i){const p=m.parts[i];$('#map-detail').innerHTML=`<h3>${esc(p[0])}</h3>${paragraphs(p[2])}<button data-lesson="${p[3]}">Read this lesson</button>`;document.querySelectorAll('[data-map-part]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.mapPart===i)))}document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>mapHome(b.dataset.map));document.querySelectorAll('[data-map-part]').forEach(b=>b.onclick=()=>detail(+b.dataset.mapPart));$('#grid-map').onclick=stakeholderGrid;detail(0)}
function stakeholderGrid(){const cells=[['High power · low interest','Keep satisfied','An influential executive who does not need daily detail still needs their key expectations addressed.'],['High power · high interest','Manage closely','A highly involved sponsor can shape decisions and needs close engagement.'],['Low power · low interest','Monitor appropriately','Watch for relevant impacts or changing interest. Low classification does not remove ethical obligations.'],['Low power · high interest','Keep informed','Affected users may care deeply even without budget authority. Provide clear updates and ways to raise concerns.']];$('#app').innerHTML=heading('Power–interest grid','Chapter 3 · Power increases upward; interest increases to the right.')+`<section class="card"><p><b>Power</b> = influence or authority. <b>Interest</b> = concern or attention, which can include opposition.</p><div class="grid power-grid">${cells.map((c,i)=>`<button data-grid="${i}"><span class="tiny">${c[0]}</span><h3>${c[1]}</h3></button>`).join('')}</div><div class="notice" id="grid-detail" aria-live="polite">Select a quadrant for a concrete example.</div><div class="actions"><button data-lesson="48">Learn the rule</button><button id="grid-practice">Practice stakeholder scenarios</button></div></section>`;document.querySelectorAll('[data-grid]').forEach(b=>b.onclick=()=>{$('#grid-detail').textContent=cells[+b.dataset.grid][2]});$('#grid-practice').onclick=()=>start('practice',shuffle(D.checks.filter(x=>x.source===48)))}
function readingsHome(openSlide=null){const chapters=section?[section]:D.sections.map(s=>s.id);$('#app').innerHTML=heading('Slides & sources','All 183 supplied slides, with text, embedded diagrams, and images kept for reference.')+`<div class="notice">Study lessons explain the concepts; this library preserves the source material. Some slides are titles, images, reflection prompts, or classroom activities. These are reference content, not instructions for the app to perform. Dated statistics, forecasts, account policies, and course estimates retain their context. Images may use the original slide’s styling.</div>`+chapters.map(ch=>`<section class="card" style="margin-top:24px"><h2>Chapter ${ch} · ${esc(sec(ch).title)}</h2><p>${SLIDES[ch].length} slides</p>${SLIDES[ch].map(s=>`<details id="source-${ch}-${s.slide}" ${openSlide===s.slide?'open':''}><summary>Slide ${s.slide} · ${esc((s.text.split('\n').find(t=>t.trim()&&!/^\d+$/.test(t.trim()))||'Image / diagram').trim())}</summary><div class="lesson-copy">${paragraphs(s.text)}${s.diagram?'<h3>Diagram text</h3>'+paragraphs(s.diagram):''}</div>${s.images.map((img,i)=>`<figure class="source-figure"><img loading="lazy" src="${esc(img)}" alt="Original illustration ${i+1} from Chapter ${ch}, slide ${s.slide}"><figcaption>Original slide illustration · Chapter ${ch}, slide ${s.slide}</figcaption></figure>`).join('')}${s.notes?`<details><summary>Speaker notes and source URLs</summary>${paragraphs(s.notes)}</details>`:''}</details>`).join('')}</section>`).join('')+`<section class="card" style="margin-top:24px"><h2>Clarification references</h2><ul>${D.references.map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title)}</a></li>`).join('')}</ul></section>`;const picker=$('#section');if(picker)picker.onchange=()=>{section=+picker.value;readingsHome()};if(openSlide)$('#source-'+section+'-'+openSlide)?.scrollIntoView({block:'start'})}

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view)navigate(b.dataset.view);else if(b.dataset.sourceChapter){section=+b.dataset.sourceChapter;view='readings';session=null;chrome();readingsHome(+b.dataset.sourceSlide)}else if(b.dataset.lesson)openLesson(+b.dataset.lesson);else if(b.dataset.practiceSection){section=+b.dataset.practiceSection;view='practice';start('practice',shuffle(filtered(D.questions)))}else if(b.dataset.question)start('practice',[D.questions.find(q=>q.number===+b.dataset.question)]);else if(b.dataset.sort)start('practice',[{...D.sorts.find(x=>x.id===b.dataset.sort),kind:'sort'}])});
Promise.all([fetch('cis464-content.json',{cache:'no-store'}),fetch('cis464-slides.json',{cache:'no-store'})].map(async r=>{const response=await r;if(!response.ok)throw Error('Content unavailable');return response.json()})).then(([data,slides])=>{D=data;SLIDES=slides;render()}).catch(()=>{$('#app').innerHTML='<section class="card"><h1>Study content could not load</h1><p>Refresh to retry loading the CIS 464 chapter content and slides.</p><button onclick="location.reload()">Try again</button></section>'});
